import {initialAccessState} from "./fixtures/access";
import {mockAdminServer,switchTestActor} from "./fixtures/admin-server";
import { test, expect, type Page } from '@playwright/test';
test.beforeEach(async({page},info)=>{if(!info.title.startsWith('Khmer'))await page.addInitScript(()=>localStorage.setItem('onebite-language','en'));});
async function open(page:Page,state?:ReturnType<typeof initialAccessState>){await mockAdminServer(page,state);await page.addInitScript(()=>localStorage.setItem('onebite-admin-session',JSON.stringify({token:'a'.repeat(64),expiresAt:Date.now()+3600000})));await page.goto('http://127.0.0.1:5174');await expect(page.locator('.access-main')).toBeVisible();}
async function startLive(page:Page,state:any){
 await page.route('**/functions/v1/admin-access',async route=>{const {action}=route.request().postDataJSON();if(action==='bootstrap.status')return route.fulfill({json:{ownerCreated:true}});if(action==='login')return route.fulfill({json:{actor:state.users.find((u:any)=>u.id==='owner'),state,session:'a'.repeat(64)}});return route.fallback();});
 await page.goto('http://127.0.0.1:5174');await page.getByLabel('Username',{exact:true}).fill('test.owner');await page.getByLabel('6-digit PIN',{exact:true}).fill('739284');await page.getByRole('button',{name:'Sign in',exact:true}).click();await expect(page.locator('.ob-sync')).toBeVisible();
}
async function choose(page:Page,label:string,value:string){if(label==='Preview identity'){await switchTestActor(page,value);return;}if(label==='Filter status'){await page.evaluate(()=>window.scrollTo({top:0,behavior:'instant'}));await expect(page.locator('.ob-directory-tools')).not.toHaveClass(/is-scroll-hidden/);await page.getByRole('group',{name:label,exact:true}).getByRole('button',{name:value==='active'?'Active':value==='inactive'?'Inactive':'All',exact:true}).click();return;}const trigger=page.getByLabel(label,{exact:true});await trigger.click();await page.locator(`[role="option"][data-value="${value}"]`).click();await expect(page.getByRole('listbox')).toHaveCount(0);await expect(trigger).toBeFocused();}
async function pickLogRange(page:Page,start:string,end:string){
 await page.getByRole('button',{name:/^Date range:/}).click();const dialog=page.getByRole('dialog');await dialog.getByRole('button',{name:'All dates',exact:true}).click();
 const [year,month]=start.split('-');await choose(page,'Year',year);await choose(page,'Month',String(Number(month)-1));
 await dialog.locator(`[data-day="${start}"] button`).click();await dialog.locator(`[data-day="${end}"] button`).click();await dialog.getByRole('button',{name:'Show logs',exact:true}).click();await expect(dialog).toHaveCount(0);
}
async function viewUser(page:Page,name:string){await page.locator('.access-user-row').filter({hasText:name}).click();await expect(page.getByRole('dialog').getByRole('heading',{name:'User details',exact:true})).toBeVisible();}
async function editUser(page:Page,name:string){await viewUser(page,name);await page.getByRole('dialog').getByRole('button',{name:'Edit',exact:true}).click();}
async function reviewRole(page:Page,role:string){await expect(page.getByRole('dialog')).toHaveCount(0);await expect(page.locator('.access-main')).not.toHaveAttribute('aria-hidden','true');const row=page.locator('.access-role-row').filter({has:page.getByRole('heading',{name:role,exact:true})});const review=row.getByRole('button',{name:'Review permissions',exact:true});await review.click();}
async function tab(page:Page,name:string){
 await expect(page.locator('.access-main')).toBeVisible();
 if(page.viewportSize()!.width>680){await page.locator('.access-sidebar nav').getByRole('button',{name,exact:true}).click();return;}
 await page.evaluate(()=>new Promise<void>(resolve=>{window.scrollTo({top:0,behavior:'instant'});requestAnimationFrame(()=>requestAnimationFrame(()=>resolve()));}));const nav=page.locator('.access-bottom-nav');await expect(nav).not.toHaveClass(/is-scroll-hidden/);await expect(nav).not.toHaveAttribute('inert','');await expect(nav).not.toHaveAttribute('aria-hidden','true');
 if(['App settings','Permissions'].includes(name)){await nav.getByRole('button',{name:'Hub',exact:true}).click();await page.locator('.access-hub-grid').getByRole('button',{name,exact:true}).click();}
 else await nav.getByRole('button',{name:name==='Site'?'Sites':name==='Activity'?'Logs':name,exact:true}).click();
}
